import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import path from 'node:path';
import { importTurtleFull } from '../../../src/lib/rdf/import-ttl.js';
import { standingOf } from '../../../src/lib/rdf/statement-standing.js';
import { buildProposals, buildScan, plyBytes } from '../build-review-examples.js';

/** The review example spaces (2026-11-10): synthetic, regenerated by scripts/starter/build-review-examples.ts. */
const file = (f: string) => readFileSync(path.resolve(__dirname, '..', '..', '..', 'static', f), 'utf8');

describe('review example spaces', () => {
  it('the proposals file is current and holds all four standings, two options and at least two questions', async () => {
    expect(file('starter-review-proposals.ttl')).toBe(buildProposals());
    const { statements } = await importTurtleFull(file('starter-review-proposals.ttl'));
    const standings = new Set(statements.map(standingOf));
    expect([...standings].sort()).toEqual(['held', 'pending', 'proposed', 'question']);
    expect(new Set(statements.map((s) => s.proposalOption).filter(Boolean)).size).toBe(2);
    expect(statements.filter((s) => s.needsObject).length).toBeGreaterThanOrEqual(2);
  });

  it('the scan file is current, links one splat to its capture and leaves one as an open question', async () => {
    expect(file('starter-review-scan.ttl')).toBe(buildScan());
    const { statements } = await importTurtleFull(file('starter-review-scan.ttl'));
    expect(statements.filter((s) => s.p.value === 'urn:kbase:predicate/reconstructed-from' && !s.needsObject)).toHaveLength(1);
    expect(statements.filter((s) => s.needsObject && s.question === 'Which capture is this a scan of?')).toHaveLength(1);
    expect(statements.filter((s) => s.p.value === 'urn:kbase:predicate/splat')).toHaveLength(2);
  });

  it('the splat files on disk are the synthetic ones this script makes', () => {
    const dir = path.resolve(__dirname, '..', '..', '..', 'static', 'generated', 'review-scan');
    expect(readFileSync(path.join(dir, 'scan-linked.ply')).equals(plyBytes(400, 'grid'))).toBe(true);
    expect(readFileSync(path.join(dir, 'scan-unlinked.ply')).equals(plyBytes(120, 'ring'))).toBe(true);
  });

  it('the jobs file shows several states, and one job with more than 20 runs keeps 20 run nodes and a count', async () => {
    const { statements } = await importTurtleFull(file('starter-review-jobs.ttl'));
    const states = new Set(statements.filter((s) => s.p.value === 'urn:kbase:predicate/job-state').map((s) => s.o.value));
    expect([...states]).toEqual(expect.arrayContaining(['running', 'queued', 'held', 'given-up']));
    expect(statements.some((s) => s.p.value === 'urn:kbase:predicate/run-count' && s.o.value === '26')).toBe(true);
    expect(statements.some((s) => s.p.value === 'urn:kbase:predicate/older-runs' && s.o.value === '6')).toBe(true);
  });
});
